function sessionStatus(time, now) {
    if (!time)
        return null;
    const [h, m] = time.split(':').map(Number);
    if (!Number.isFinite(h))
        return null;
    const diff = h * 60 + (Number.isFinite(m) ? m : 0) - (now.getHours() * 60 + now.getMinutes());
    if (diff < -45)
        return { label: 'הסתיים', bg: 'var(--line-soft)', c: 'var(--ink-faint)' };
    if (diff <= 45)
        return { label: 'מתקיים כעת', bg: 'color-mix(in srgb, var(--green) 14%, var(--panel))', c: 'var(--green)' };
    return { label: 'בהמשך היום', bg: 'var(--stat-tint)', c: 'var(--accent-deep)' };
}
